INSERT INTO `notice` VALUES (2039, '兽医学院新发和人兽共患病创新研究团队揭示隐孢子虫毒力的遗传决定因素', '<p>	<span style=\"color: rgb(51, 51, 51);\">近日，我校兽医学院肖立华和冯耀宇教授团队在病原生物学领域取得重大突破，并在国际知名期刊Nature Communications在线发表题为“SKSR1 identified as key virulence factor in Cryptosporidium&nbsp;by genetic crossing”的研究论文。该研究首次采用正向和反向遗传学手段揭示人兽共患微小隐孢子虫（Cryptosporidium parvum）毒力的遗传决定因素，为隐孢子虫病的防控提供了重要理论依据。</span></p>', '2025-06-04', 'http://localhost:8086/files/1749011032690-noti01.png');
